        import yaml
        stringDeserializer = yaml.load
        data = stringDeserializer(json_str, Loader=yaml.Loader)
    except Exception:
        return {}
    url_pattern = re.compile(r'https?://[^\s<>"\']+')
    urls = []
    def extract(obj):
        if isinstance(obj, str):
            urls.extend(url_pattern.findall(obj))
        elif isinstance(obj, dict):
            for v in obj.values():
                extract(v)
        elif isinstance(obj, list):
            for item in obj:
                extract(item)
    extract(data)
    return dict(Counter(urls).most_common(top_n))
